<script setup>
import {ref,computed} from 'vue'
import {readConfig,quotePlan} from './config'
const props=defineProps({activeStudents:Number})
const config=readConfig(),students=ref(props.activeStudents??config.students),tier=ref(config.tier),quote=computed(()=>{try{return quotePlan(Number(students.value),tier.value,config.prices)}catch{return null}})
</script>
<template><div class="page-heading"><div><span class="eyebrow">GROW AT YOUR OWN PACE</span><h1>Simple plans. Room to grow.</h1><p>Your first 100 active students are free. Choose a plan as your community grows.</p></div><span class="badge violet">Pricing preview · no charge</span></div><section class="panel launch-price"><div class="form-row"><label>Active students<input v-model.number="students" type="number" min="0" max="1000000"></label><label>Commercial market tier<select v-model="tier"><option v-for="t in 'ABCDE'">{{t}}</option></select></label></div><div v-if="quote" class="launch-price-summary"><div><small>YOUR PLAN</small><h2>{{quote.id}}</h2><p>{{students}} active students · archived students excluded</p></div><strong>{{quote.amount===null?'Custom quote':quote.amount===0?'Free':'US$'+quote.amount}}<small v-if="quote.amount"> / month reference</small></strong></div><p>Country prices are approved commercial tables, not exchange-rate conversions. Final currency, taxes, usage fees and contract terms are shown before purchase.</p></section><div class="launch-plan-grid"><article v-for="row in config.prices" class="panel" :class="{current:quote?.id===row.id}"><span class="badge violet">{{row.id}}</span><h2>{{row.prices['ABCDE'.indexOf(tier)]===null?'Let’s talk':row.prices['ABCDE'.indexOf(tier)]===0?'Free':'US$'+row.prices['ABCDE'.indexOf(tier)]}}</h2><p>{{row.id==='Enterprise'?'5,001+':('Up to '+row.max)}} active students</p><small>{{quote?.id===row.id?'Your estimated plan':'Monthly reference · no checkout yet'}}</small></article></div><section class="panel launch-price"><h2>A clear bill, every month.</h2><p>Calendar-month usage, with plan charges, pay-as-you-go services, taxes, discounts and credits itemized separately. Card details belong with the payment provider; Sisu stores only safe payment references.</p><span class="badge peach">Card billing connection pending</span><h3>Optional services</h3><div class="launch-addon-list"><span v-for="a in config.payg">{{a.name}}<strong>US${{a.price}} / month reference</strong></span></div><p class="field-help">SMS is priced per country and provider. Postpaid services require a verified payment method or approved enterprise invoice contract. Failed payments follow grace/retry rules; they do not delete customer data.</p></section></template>
<style>.launch-price{padding:30px;margin-bottom:25px}.launch-price label{display:flex;flex-direction:column;gap:9px;font-size:12px}.launch-price input,.launch-price select{padding:12px;border-radius:10px;border:1px solid var(--student-border);background:var(--student-card);color:var(--student-ink)}.launch-price-summary{display:flex;align-items:center;justify-content:space-between;padding:30px 0;gap:25px}.launch-price-summary h2{font-size:32px;margin:12px 0}.launch-price-summary>strong{font-size:32px}.launch-price-summary small{font-size:12px}.launch-price p{font-size:12px;line-height:1.9}.launch-plan-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:16px;margin-bottom:25px}.launch-plan-grid>article{padding:25px}.launch-plan-grid h2{font-size:29px;margin:22px 0}.launch-plan-grid p{font-size:12px}.launch-plan-grid small{font-size:10px}.launch-plan-grid .current{border-color:var(--student-accent);background:var(--student-soft)}.launch-addon-list{display:grid;grid-template-columns:repeat(2,1fr);gap:14px;margin:25px 0}.launch-addon-list span{border-bottom:1px solid var(--student-border);padding:14px 0;font-size:12px}.launch-addon-list strong{display:block;margin-top:10px}@media(max-width:600px){.launch-price-summary{align-items:flex-start;flex-direction:column}.launch-addon-list{grid-template-columns:1fr}}</style>
